    ! ---------------------------------------------------------------------------------------------
    !> Coefficient spi1 of horndeski_perturbeq_coefficients.
    subroutine horndeski_perturbeq_coefficients_spi1(a, H, dH, ddH, dphi, ddphi, dddphi, rptot, drptot, G2, G2p, &
        G2x, G2pp, G2px, G2xx, G2ppp, G2ppx, G2pxx, G2xxx, G3p, G3x, G3pp, G3px, G3xx, G3ppp, G3ppx, G3pxx, G3xxx, &
        G4, G4p, G4x, G4pp, G4px, G4xx, G4ppp, G4ppx, G4pxx, G4xxx, G4pppp, G4pppx, G4ppxx, G4pxxx, G4xxxx, G5, G5p, &
        G5x, G5pp, G5px, G5xx, G5ppp, G5ppx, G5pxx, G5xxx, G5pppp, G5pppx, G5ppxx, G5pxxx, G5xxxx, spi1)

    implicit none

    real(c_double), intent(in) :: a, H, dH, ddH, dphi, ddphi, dddphi, rptot, drptot, G2, G2p, G2x
    real(c_double), intent(in) :: G2pp, G2px, G2xx, G2ppp, G2ppx, G2pxx, G2xxx, G3p, G3x, G3pp, G3px, G3xx
    real(c_double), intent(in) :: G3ppp, G3ppx, G3pxx, G3xxx, G4, G4p, G4x, G4pp, G4px, G4xx, G4ppp, G4ppx
    real(c_double), intent(in) :: G4pxx, G4xxx, G4pppp, G4pppx, G4ppxx, G4pxxx, G4xxxx, G5, G5p, G5x, G5pp, G5px
    real(c_double), intent(in) :: G5xx, G5ppp, G5ppx, G5pxx, G5xxx, G5pppp, G5pppx, G5ppxx, G5pxxx, G5xxxx
    real(c_double), intent(out) :: spi1

    ! Milestone spi1
    spi1 = ((-12._dl) * a**11 * G4p**2 * H + ddphi * dphi**9 * (3._dl * G5xx * G5xxx - 2._dl * G5x * G5xxxx) * H**4 &
        + a * dphi**8 * H**3 * ((-2._dl) * ddphi * (6._dl * G4xxxx * G5x - 3._dl * G5pxxx * G5x - 6._dl * G4xxx * &
        G5xx + 3._dl * G5pxx * G5xx - 6._dl * G4xx * G5xxx + 3._dl * G5px * G5xxx + 2._dl * G4x * G5xxxx - G5p * &
        G5xxxx) + dphi**2 * ((-3._dl) * G5xx * G5xxx + 2._dl * G5x * G5xxxx) * H**2) + a**2 * dphi**7 * H**2 * (dphi &
        * H * (6._dl * dH * (G5xx**2 - G5x * G5xxx) + dphi * (12._dl * G4xxxx * G5x - 8._dl * G5pxxx * G5x - 12._dl &
        * G4xxx * G5xx + 9._dl * G5pxx * G5xx - 12._dl * G4xx * G5xxx + 6._dl * G5px * G5xxx + 4._dl * G4x * G5xxxx &
        - 2._dl * G5p * G5xxxx) * H) + 3._dl * ddphi * (16._dl * G4xx * G4xxx - 8._dl * G4x * G4xxxx + 4._dl * &
        G4xxxx * G5p - 8._dl * G4xxx * G5px - 8._dl * G4xx * G5pxx + 4._dl * G5px * G5pxx + 4._dl * G4x * G5pxxx - &
