        G5xx + 2._dl * G5x * G5xx * H**2) - 2._dl * a**3 * dphi**5 * H * ((-12._dl) * G3x * G4xx + 24._dl * G4px * &
        G4xx + G3xx * (6._dl * G4x - 3._dl * G5p) + 6._dl * G4pxx * ((-2._dl) * G4x + G5p) + 6._dl * G3x * G5px - &
        12._dl * G4px * G5px + G2xx * G5x - G3px * G5x - 12._dl * G4xx * G5x * H**2 + 3._dl * G5px * G5x * H**2 + &
        2._dl * G4x * G5xx * H**2 + 5._dl * G5p * G5xx * H**2 - 2._dl * G4 * G5xxx * H**2) + a**4 * dphi**4 * (3._dl &
        * G3x**2 - 12._dl * G3x * G4px + 12._dl * G4px**2 - 4._dl * G2xx * G4x + 4._dl * G3px * G4x + 2._dl * G2xx * &
        G5p - 2._dl * G3px * G5p + 24._dl * G4 * G4xxx * H**2 - 48._dl * G4xx * G5p * H**2 + 12._dl * G4x * G5px * &
        H**2 + 18._dl * G5p * G5px * H**2 - 12._dl * G4 * G5pxx * H**2 + 6._dl * G3x * G5x * H**2 - 12._dl * G4p * &
        G5xx * H**2 + 15._dl * G5x**2 * H**4)))

    end subroutine horndeski_perturbeq_coefficients_spih

    ! ---------------------------------------------------------------------------------------------
    !> Coefficient spie of horndeski_perturbeq_coefficients.
    subroutine horndeski_perturbeq_coefficients_spie(a, H, dH, ddH, dphi, ddphi, dddphi, rptot, drptot, G2, G2p, &
        G2x, G2pp, G2px, G2xx, G2ppp, G2ppx, G2pxx, G2xxx, G3p, G3x, G3pp, G3px, G3xx, G3ppp, G3ppx, G3pxx, G3xxx, &
        G4, G4p, G4x, G4pp, G4px, G4xx, G4ppp, G4ppx, G4pxx, G4xxx, G4pppp, G4pppx, G4ppxx, G4pxxx, G4xxxx, G5, G5p, &
        G5x, G5pp, G5px, G5xx, G5ppp, G5ppx, G5pxx, G5xxx, G5pppp, G5pppx, G5ppxx, G5pxxx, G5xxxx, spie)

    implicit none

    real(c_double), intent(in) :: a, H, dH, ddH, dphi, ddphi, dddphi, rptot, drptot, G2, G2p, G2x
    real(c_double), intent(in) :: G2pp, G2px, G2xx, G2ppp, G2ppx, G2pxx, G2xxx, G3p, G3x, G3pp, G3px, G3xx
    real(c_double), intent(in) :: G3ppp, G3ppx, G3pxx, G3xxx, G4, G4p, G4x, G4pp, G4px, G4xx, G4ppp, G4ppx
    real(c_double), intent(in) :: G4pxx, G4xxx, G4pppp, G4pppx, G4ppxx, G4pxxx, G4xxxx, G5, G5p, G5x, G5pp, G5px
    real(c_double), intent(in) :: G5xx, G5ppp, G5ppx, G5pxx, G5xxx, G5pppp, G5pppx, G5ppxx, G5pxxx, G5xxxx
    real(c_double), intent(out) :: spie

    ! Milestone spie
    spie = ((-2._dl) * a * H * (4._dl * a**8 * G4 * G4p + 8._dl * a**7 * dphi * G4 * (G4x - G5p) * H + ddphi * &
        dphi**6 * G5x * G5xx * H**2 - 2._dl * a**5 * dphi * (2._dl * dH * dphi * G4 * G5x + 4._dl * ddphi * G4 * G5x &
        * H + dphi**2 * ((-8._dl) * G4 * G4xx + 2._dl * G4x * G5p - 2._dl * G5p**2 + 6._dl * G4 * G5px + 3._dl * G4p &
        * G5x) * H) - a * dphi**5 * G5xx * H * ((-4._dl) * ddphi * G4x + 2._dl * ddphi * G5p + dphi**2 * G5x * H**2) &
        + 2._dl * a**6 * (4._dl * ddphi * G4 * ((-G4x) + G5p) + dphi**2 * (G3x * G4 - 6._dl * G4 * G4px - 4._dl * &
        G4p * G4x + 3._dl * G4p * G5p + 2._dl * G4 * G5pp + 5._dl * G4 * G5x * H**2)) + a**2 * dphi**4 * (dphi * H * &
        (2._dl * dH * G5x**2 + dphi * (2._dl * G5px * G5x - 4._dl * G4x * G5xx + G5p * G5xx) * H) + ddphi * (8._dl * &
        G4x * G4xx - 4._dl * G4xx * G5p - 4._dl * G4x * G5px + 2._dl * G5p * G5px - G3x * G5x + 2._dl * G4px * G5x + &
        G5x**2 * H**2)) + a**4 * (2._dl * ddphi * dphi**2 * (4._dl * G4x**2 - 4._dl * G4 * G4xx - 6._dl * G4x * G5p &
        + 2._dl * G5p**2 + 2._dl * G4 * G5px + G4p * G5x) + dphi**4 * (8._dl * G4px * G4x - G3x * G5p - 2._dl * G4px &
        * G5p - 4._dl * G4x * G5pp + 2._dl * G5p * G5pp - 5._dl * G5p * G5x * H**2 + 6._dl * G4 * G5xx * H**2)) + &
        a**3 * dphi**3 * (2._dl * dH * dphi * (2._dl * G4x - G5p) * G5x + 4._dl * ddphi * (2._dl * G4x * G5x - G5p * &
        G5x - G4 * G5xx) * H + dphi**2 * H * ((-8._dl) * G4x * (G4xx - G5px) - 2._dl * G5p * G5px + G5x * (G3x + &
        2._dl * G4px - 2._dl * G5pp + G5x * H**2))))) / ((-2._dl) * a * dphi**7 * (6._dl * G4xxx * G5x - 3._dl * &
        G5pxx * G5x - 12._dl * G4xx * G5xx + 6._dl * G5px * G5xx + 2._dl * G4x * G5xxx - G5p * G5xxx) * H**3 + &
        dphi**8 * (3._dl * G5xx**2 - 2._dl * G5x * G5xxx) * H**4 + 4._dl * a**8 * (G2x * G4 - 2._dl * G3p * G4 + &
        3._dl * G4p**2 + 6._dl * G4 * G4x * H**2 - 6._dl * G4 * G5p * H**2) + 24._dl * a**7 * dphi * H * (G3x * G4 - &
        3._dl * G4 * G4px - 2._dl * G4p * G4x + 2._dl * G4p * G5p + G4 * G5x * H**2) + 2._dl * a**6 * dphi**2 * &
        (2._dl * G2xx * G4 - 2._dl * G3px * G4 - 6._dl * G3x * G4p + 12._dl * G4p * G4px - 2._dl * G2x * G4x + 4._dl &
        * G3p * G4x + G2x * G5p - 2._dl * G3p * G5p + 12._dl * G4x**2 * H**2 + 48._dl * G4 * G4xx * H**2 - 30._dl * &
        G4x * G5p * H**2 + 18._dl * G5p**2 * H**2 - 30._dl * G4 * G5px * H**2 - 18._dl * G4p * G5x * H**2) + 2._dl * &
        a**5 * dphi**3 * H * (6._dl * G3xx * G4 - 12._dl * G4 * G4pxx + 12._dl * G4px * G4x - 24._dl * G4p * G4xx - &
        6._dl * G3x * G5p + 6._dl * G4px * G5p + 12._dl * G4p * G5px - G2x * G5x + 2._dl * G3p * G5x + 18._dl * G4x &
        * G5x * H**2 - 24._dl * G5p * G5x * H**2 + 14._dl * G4 * G5xx * H**2) + 2._dl * a**2 * dphi**6 * H**2 * &
        (24._dl * G4xx**2 + 6._dl * G4xxx * G5p - 24._dl * G4xx * G5px + 6._dl * G5px**2 - 3._dl * G5p * G5pxx + &
        6._dl * G4x * ((-2._dl) * G4xxx + G5pxx) - 3._dl * G3xx * G5x + 6._dl * G4pxx * G5x + 3._dl * G3x * G5xx - &
        6._dl * G4px * G5xx + 2._dl * G5x * G5xx * H**2) - 2._dl * a**3 * dphi**5 * H * ((-12._dl) * G3x * G4xx + &
        24._dl * G4px * G4xx + G3xx * (6._dl * G4x - 3._dl * G5p) + 6._dl * G4pxx * ((-2._dl) * G4x + G5p) + 6._dl * &
        G3x * G5px - 12._dl * G4px * G5px + G2xx * G5x - G3px * G5x - 12._dl * G4xx * G5x * H**2 + 3._dl * G5px * &
        G5x * H**2 + 2._dl * G4x * G5xx * H**2 + 5._dl * G5p * G5xx * H**2 - 2._dl * G4 * G5xxx * H**2) + a**4 * &
        dphi**4 * (3._dl * G3x**2 - 12._dl * G3x * G4px + 12._dl * G4px**2 - 4._dl * G2xx * G4x + 4._dl * G3px * G4x &
        + 2._dl * G2xx * G5p - 2._dl * G3px * G5p + 24._dl * G4 * G4xxx * H**2 - 48._dl * G4xx * G5p * H**2 + 12._dl &
        * G4x * G5px * H**2 + 18._dl * G5p * G5px * H**2 - 12._dl * G4 * G5pxx * H**2 + 6._dl * G3x * G5x * H**2 - &
        12._dl * G4p * G5xx * H**2 + 15._dl * G5x**2 * H**4))

    end subroutine horndeski_perturbeq_coefficients_spie

    ! ---------------------------------------------------------------------------------------------
    !> Coefficient spim of horndeski_perturbeq_coefficients.
    subroutine horndeski_perturbeq_coefficients_spim(a, H, dH, ddH, dphi, ddphi, dddphi, rptot, drptot, G2, G2p, &
        G2x, G2pp, G2px, G2xx, G2ppp, G2ppx, G2pxx, G2xxx, G3p, G3x, G3pp, G3px, G3xx, G3ppp, G3ppx, G3pxx, G3xxx, &
