    real(c_double), intent(in) :: G2pp, G2px, G2xx, G2ppp, G2ppx, G2pxx, G2xxx, G3p, G3x, G3pp, G3px, G3xx
    real(c_double), intent(in) :: G3ppp, G3ppx, G3pxx, G3xxx, G4, G4p, G4x, G4pp, G4px, G4xx, G4ppp, G4ppx
    real(c_double), intent(in) :: G4pxx, G4xxx, G4pppp, G4pppx, G4ppxx, G4pxxx, G4xxxx, G5, G5p, G5x, G5pp, G5px
    real(c_double), intent(in) :: G5xx, G5ppp, G5ppx, G5pxx, G5xxx, G5pppp, G5pppx, G5ppxx, G5pxxx, G5xxxx
    real(c_double), intent(out) :: spim

    ! Milestone spim
    spim = (3._dl * a**6 * ((-2._dl) * a**4 * G4p + 4._dl * a**3 * dphi * (G4x - G5p) * H + 2._dl * a * dphi**3 * &
        (2._dl * G4xx - G5px) * H + dphi**4 * G5xx * H**2 + a**2 * dphi**2 * (G3x - 2._dl * G4px + 3._dl * G5x * &
        H**2))) / (3._dl * ((-2._dl) * a**4 * G4p + 4._dl * a**3 * dphi * (G4x - G5p) * H + 2._dl * a * dphi**3 * &
        (2._dl * G4xx - G5px) * H + dphi**4 * G5xx * H**2 + a**2 * dphi**2 * (G3x - 2._dl * G4px + 3._dl * G5x * &
        H**2))**2 + 2._dl * (2._dl * a**3 * G4 + a * dphi**2 * ((-2._dl) * G4x + G5p) - dphi**3 * G5x * H) * (3._dl &
        * a * dphi**4 * (2._dl * G4xxx - G5pxx) * H**2 + dphi**5 * G5xxx * H**3 + a**3 * dphi**2 * (G2xx - G3px + &
        3._dl * (8._dl * G4xx - 5._dl * G5px) * H**2) + 6._dl * a**4 * dphi * H * (G3x - 3._dl * G4px + G5x * H**2) &
        + a**2 * dphi**3 * H * (3._dl * G3xx - 6._dl * G4pxx + 7._dl * G5xx * H**2) + a**5 * (G2x - 2._dl * (G3p + &
        3._dl * ((-G4x) + G5p) * H**2))))

