    subroutine horndeski_perturbeq_coefficients_s00(a, H, dH, ddH, dphi, ddphi, dddphi, rptot, drptot, G2, G2p, G2x, &
        G2pp, G2px, G2xx, G2ppp, G2ppx, G2pxx, G2xxx, G3p, G3x, G3pp, G3px, G3xx, G3ppp, G3ppx, G3pxx, G3xxx, G4, &
