    real(c_double), intent(out) :: s00

    ! Milestone s00
    s00 = ((-2._dl) * a * (6._dl * a**4 * dphi * G4pp * H + 3._dl * a * dphi**4 * ((-2._dl) * G4pxx + G5ppx) * H**2 &
        - dphi**5 * G5pxx * H**3 + a**5 * (G2p + 6._dl * G4p * H**2) + a**3 * dphi**2 * ((-G2px) + G3pp + 3._dl * &
        ((-4._dl) * G4px + 3._dl * G5pp) * H**2) + a**2 * dphi**3 * H * ((-3._dl) * G3px + 6._dl * G4ppx - 5._dl * &
        G5px * H**2))) / (2._dl * a**4 * dphi * G4p + 4._dl * a**5 * G4 * H + 2._dl * a**3 * dphi**2 * ((-4._dl) * &
        G4x + 3._dl * G5p) * H + 2._dl * a * dphi**4 * ((-2._dl) * G4xx + G5px) * H - dphi**5 * G5xx * H**2 - a**2 * &
        dphi**3 * (G3x - 2._dl * G4px + 5._dl * G5x * H**2))

