        G4xxx * H**2 - 48._dl * G4xx * G5p * H**2 + 12._dl * G4x * G5px * H**2 + 18._dl * G5p * G5px * H**2 - 12._dl &
        * G4 * G5pxx * H**2 + 6._dl * G3x * G5x * H**2 - 12._dl * G4p * G5xx * H**2 + 15._dl * G5x**2 * H**4)))

    end subroutine horndeski_perturbeq_coefficients_siip

    ! ---------------------------------------------------------------------------------------------
    !> Coefficient siipp of horndeski_perturbeq_coefficients.
    subroutine horndeski_perturbeq_coefficients_siipp(a, H, dH, ddH, dphi, ddphi, dddphi, rptot, drptot, G2, G2p, &
        G2x, G2pp, G2px, G2xx, G2ppp, G2ppx, G2pxx, G2xxx, G3p, G3x, G3pp, G3px, G3xx, G3ppp, G3ppx, G3pxx, G3xxx, &
        G4, G4p, G4x, G4pp, G4px, G4xx, G4ppp, G4ppx, G4pxx, G4xxx, G4pppp, G4pppx, G4ppxx, G4pxxx, G4xxxx, G5, G5p, &
        G5x, G5pp, G5px, G5xx, G5ppp, G5ppx, G5pxx, G5xxx, G5pppp, G5pppx, G5ppxx, G5pxxx, G5xxxx, siipp)

    implicit none

    real(c_double), intent(in) :: a, H, dH, ddH, dphi, ddphi, dddphi, rptot, drptot, G2, G2p, G2x
    real(c_double), intent(in) :: G2pp, G2px, G2xx, G2ppp, G2ppx, G2pxx, G2xxx, G3p, G3x, G3pp, G3px, G3xx
    real(c_double), intent(in) :: G3ppp, G3ppx, G3pxx, G3xxx, G4, G4p, G4x, G4pp, G4px, G4xx, G4ppp, G4ppx
    real(c_double), intent(in) :: G4pxx, G4xxx, G4pppp, G4pppx, G4ppxx, G4pxxx, G4xxxx, G5, G5p, G5x, G5pp, G5px
    real(c_double), intent(in) :: G5xx, G5ppp, G5ppx, G5pxx, G5xxx, G5pppp, G5pppx, G5ppxx, G5pxxx, G5xxxx
    real(c_double), intent(out) :: siipp

    ! Milestone siipp
    siipp = (3._dl * ((-2._dl) * a**4 * G4p + 4._dl * a**3 * dphi * (G4x - G5p) * H + 2._dl * a * dphi**3 * (2._dl * &
        G4xx - G5px) * H + dphi**4 * G5xx * H**2 + a**2 * dphi**2 * (G3x - 2._dl * G4px + 3._dl * G5x * H**2))) / (a &
        * (2._dl * a**3 * G4 + a * dphi**2 * ((-2._dl) * G4x + G5p) - dphi**3 * G5x * H))

    end subroutine horndeski_perturbeq_coefficients_siipp

    ! ---------------------------------------------------------------------------------------------
    !> Coefficient sij of horndeski_perturbeq_coefficients.
    subroutine horndeski_perturbeq_coefficients_sij(a, H, dH, ddH, dphi, ddphi, dddphi, rptot, drptot, G2, G2p, G2x, &
        G2pp, G2px, G2xx, G2ppp, G2ppx, G2pxx, G2xxx, G3p, G3x, G3pp, G3px, G3xx, G3ppp, G3ppx, G3pxx, G3xxx, G4, &
        G4p, G4x, G4pp, G4px, G4xx, G4ppp, G4ppx, G4pxx, G4xxx, G4pppp, G4pppx, G4ppxx, G4pxxx, G4xxxx, G5, G5p, &
        G5x, G5pp, G5px, G5xx, G5ppp, G5ppx, G5pxx, G5xxx, G5pppp, G5pppx, G5ppxx, G5pxxx, G5xxxx, sij)

    implicit none

    real(c_double), intent(in) :: a, H, dH, ddH, dphi, ddphi, dddphi, rptot, drptot, G2, G2p, G2x
    real(c_double), intent(in) :: G2pp, G2px, G2xx, G2ppp, G2ppx, G2pxx, G2xxx, G3p, G3x, G3pp, G3px, G3xx
    real(c_double), intent(in) :: G3ppp, G3ppx, G3pxx, G3xxx, G4, G4p, G4x, G4pp, G4px, G4xx, G4ppp, G4ppx
    real(c_double), intent(in) :: G4pxx, G4xxx, G4pppp, G4pppx, G4ppxx, G4pxxx, G4xxxx, G5, G5p, G5x, G5pp, G5px
    real(c_double), intent(in) :: G5xx, G5ppp, G5ppx, G5pxx, G5xxx, G5pppp, G5pppx, G5ppxx, G5pxxx, G5xxxx
    real(c_double), intent(out) :: sij

    ! Milestone sij
    sij = ((-2._dl) * a**5 * G4p + ddphi * dphi**3 * G5xx * H + a**2 * dphi * (dH * dphi * G5x + 2._dl * (dphi**2 * &
        ((-G4xx) + G5px) + ddphi * G5x) * H) - a * dphi**2 * (ddphi * ((-2._dl) * G4xx + G5px) + dphi**2 * G5xx * &
        H**2) + a**3 * (2._dl * ddphi * (G4x - G5p) + dphi**2 * (2._dl * G4px - G5pp - G5x * H**2))) / (a**2 * &
        (2._dl * a**3 * G4 + a * dphi**2 * ((-2._dl) * G4x + G5p) - dphi**3 * G5x * H))

    end subroutine horndeski_perturbeq_coefficients_sij

    ! ---------------------------------------------------------------------------------------------
    !> Coefficient sijdot of horndeski_perturbeq_coefficients.
    subroutine horndeski_perturbeq_coefficients_sijdot(a, H, dH, ddH, dphi, ddphi, dddphi, rptot, drptot, G2, G2p, &
        G2x, G2pp, G2px, G2xx, G2ppp, G2ppx, G2pxx, G2xxx, G3p, G3x, G3pp, G3px, G3xx, G3ppp, G3ppx, G3pxx, G3xxx, &
        G4, G4p, G4x, G4pp, G4px, G4xx, G4ppp, G4ppx, G4pxx, G4xxx, G4pppp, G4pppx, G4ppxx, G4pxxx, G4xxxx, G5, G5p, &
        G5x, G5pp, G5px, G5xx, G5ppp, G5ppx, G5pxx, G5xxx, G5pppp, G5pppx, G5ppxx, G5pxxx, G5xxxx, sijdot)

    implicit none

    real(c_double), intent(in) :: a, H, dH, ddH, dphi, ddphi, dddphi, rptot, drptot, G2, G2p, G2x
    real(c_double), intent(in) :: G2pp, G2px, G2xx, G2ppp, G2ppx, G2pxx, G2xxx, G3p, G3x, G3pp, G3px, G3xx
    real(c_double), intent(in) :: G3ppp, G3ppx, G3pxx, G3xxx, G4, G4p, G4x, G4pp, G4px, G4xx, G4ppp, G4ppx
    real(c_double), intent(in) :: G4pxx, G4xxx, G4pppp, G4pppx, G4ppxx, G4pxxx, G4xxxx, G5, G5p, G5x, G5pp, G5px
    real(c_double), intent(in) :: G5xx, G5ppp, G5ppx, G5pxx, G5xxx, G5pppp, G5pppx, G5ppxx, G5pxxx, G5xxxx
    real(c_double), intent(out) :: sijdot

    ! Milestone sijdot
    sijdot = (4._dl * a**10 * dphi * (G4p**2 - G4 * G4pp) + ddphi**2 * dphi**7 * (G5xx**2 - G5x * G5xxx) * H**2 + a &
        * ddphi * dphi**6 * H * (ddphi * ((-2._dl) * G4xxx * G5x + G5pxx * G5x + 4._dl * G4xx * G5xx - 2._dl * G5px &
        * G5xx - 2._dl * G4x * G5xxx + G5p * G5xxx) - 2._dl * dphi**2 * (G5xx**2 - G5x * G5xxx) * H**2) + a**2 * &
        dphi**5 * (ddphi**2 * (4._dl * G4xx**2 - 4._dl * G4x * G4xxx + 2._dl * G4xxx * G5p - 4._dl * G4xx * G5px + &
        G5px**2 + 2._dl * G4x * G5pxx - G5p * G5pxx) - dddphi * dphi * G5x * G5xx * H**2 + 2._dl * ddphi * dphi**2 * &
        (2._dl * G4xxx * G5x - 2._dl * G5pxx * G5x - 4._dl * G4xx * G5xx + 3._dl * G5px * G5xx + 2._dl * G4x * G5xxx &
        - G5p * G5xxx) * H**2 + dphi**4 * (G5xx**2 - G5x * G5xxx) * H**4) + 2._dl * a**8 * (2._dl * dddphi * G4 * &
        (G4x - G5p) - 5._dl * dH * dphi**2 * G4 * G5x * H + dphi**3 * ((-4._dl) * G4p * G4px + 2._dl * G4pp * G4x - &
        G4pp * G5p + 2._dl * G4p * G5pp + 4._dl * G4p * G5x * H**2 + G4 * (2._dl * G4ppx - G5ppp + (6._dl * G4xx - &
        7._dl * G5px) * H**2)) + 4._dl * ddphi * dphi * (G4p * ((-G4x) + G5p) + G4 * (G4px - G5pp - 2._dl * G5x * &
        H**2))) + 4._dl * a**9 * H * (2._dl * ddphi * G4 * ((-G4x) + G5p) + dphi**2 * (G4p * (G4x - G5p) + G4 * &
        ((-G4px) + G5pp + G5x * H**2))) + a**6 * dphi * (4._dl * ddphi**2 * (G4x**2 + 3._dl * G4 * G4xx - 2._dl * &
        G4x * G5p + G5p**2 - 2._dl * G4 * G5px) - 2._dl * dddphi * dphi * (2._dl * G4x**2 - 2._dl * G4 * G4xx - &
        3._dl * G4x * G5p + G5p**2 + G4 * G5px) + dH * dphi**3 * (8._dl * G4x * G5x - 3._dl * G5p * G5x - 6._dl * G4 &
        * G5xx) * H + dphi**4 * (4._dl * G4px**2 - 4._dl * G4ppx * G4x + 2._dl * G4ppx * G5p - 4._dl * G4px * G5pp + &
        G5pp**2 + 2._dl * G4x * G5ppp - G5p * G5ppp - 8._dl * G4x * G4xx * H**2 + 4._dl * G4 * G4xxx * H**2 + 2._dl &
        * G4xx * G5p * H**2 + 10._dl * G4x * G5px * H**2 - 3._dl * G5p * G5px * H**2 - 6._dl * G4 * G5pxx * H**2 - &
        6._dl * G4px * G5x * H**2 + 2._dl * G5pp * G5x * H**2 + 4._dl * G4p * G5xx * H**2 + G5x**2 * H**4) + 4._dl * &
        ddphi * dphi**2 * ((-2._dl) * G4p * G4xx - G4px * G5p + G4x * G5pp + G4p * G5px + 2._dl * G4x * G5x * H**2 + &
        G4 * (2._dl * G4pxx - G5ppx - 6._dl * G5xx * H**2))) + 2._dl * a**7 * (ddH * dphi**2 * G4 * G5x + dH * &
        (4._dl * ddphi * dphi * G4 * G5x + dphi**3 * ((-2._dl) * G4 * G4xx + 3._dl * G4 * G5px - 2._dl * G4p * G5x)) &
        + H * (2._dl * ddphi**2 * G4 * G5x + 2._dl * dddphi * dphi * G4 * G5x + ddphi * dphi**2 * (2._dl * G4x**2 - &
        16._dl * G4 * G4xx - 2._dl * G4x * G5p + 14._dl * G4 * G5px - 5._dl * G4p * G5x) + dphi**4 * ((-4._dl) * G4 &
        * G4pxx + 4._dl * G4p * G4xx + G4px * G5p - G4x * G5pp + 3._dl * G4 * G5ppx - 4._dl * G4p * G5px + G4pp * &
        G5x - G4x * G5x * H**2 + 5._dl * G4 * G5xx * H**2))) + a**3 * dphi**4 * (ddphi**2 * (4._dl * G4xx * G5x - &
        G5px * G5x - 6._dl * G4x * G5xx + G5p * G5xx + 2._dl * G4 * G5xxx) * H + dphi * H * (dddphi * ((-2._dl) * &
        G4xx * G5x + G5px * G5x - 2._dl * G4x * G5xx + G5p * G5xx) + dphi**2 * H * (dH * G5x * G5xx + dphi * &
        ((-2._dl) * G4xxx * G5x + 3._dl * G5pxx * G5x + 4._dl * G4xx * G5xx - 4._dl * G5px * G5xx - 2._dl * G4x * &
        G5xxx + G5p * G5xxx) * H)) + ddphi * dphi * (2._dl * dH * (2._dl * G4xx * G5x - G5px * G5x - 2._dl * G4x * &
        G5xx + G5p * G5xx) + dphi * H * ((-8._dl) * G4xx**2 + 8._dl * G4x * G4xxx - 4._dl * G4xxx * G5p + 12._dl * &
        G4xx * G5px - 4._dl * G5px**2 - 8._dl * G4x * G5pxx + 4._dl * G5p * G5pxx - 4._dl * G4pxx * G5x + 2._dl * &
        G5ppx * G5x + 4._dl * G4px * G5xx - 2._dl * G5pp * G5xx + 3._dl * G5x * G5xx * H**2))) + a**5 * dphi**2 * &
        (ddH * dphi**2 * ((-2._dl) * G4x + G5p) * G5x + dH * dphi * ((-4._dl) * ddphi * G4x * G5x + 4._dl * ddphi * &
        G4 * G5xx + dphi**2 * (4._dl * G4x * G4xx - 2._dl * G4xx * G5p - 6._dl * G4x * G5px + 3._dl * G5p * G5px + &
        4._dl * G4px * G5x - 2._dl * G5pp * G5x + G5x**2 * H**2)) + H * (2._dl * dddphi * dphi * ((-3._dl) * G4x * &
        G5x + 2._dl * G5p * G5x + G4 * G5xx) + 2._dl * ddphi**2 * (3._dl * G4x * G5x - 4._dl * G5p * G5x + 5._dl * &
        G4 * G5xx) + ddphi * dphi**2 * (20._dl * G4x * G4xx - 8._dl * G4 * G4xxx - 4._dl * G4xx * G5p - 18._dl * G4x &
        * G5px + 4._dl * G5p * G5px + 8._dl * G4 * G5pxx + 6._dl * G4px * G5x - G5pp * G5x - 4._dl * G4p * G5xx - &
        G5x**2 * H**2) + dphi**4 * (8._dl * G4pxx * G4x - 8._dl * G4px * G4xx - 4._dl * G4pxx * G5p + 4._dl * G4xx * &
        G5pp - 6._dl * G4x * G5ppx + 3._dl * G5p * G5ppx + 8._dl * G4px * G5px - 4._dl * G5pp * G5px - 2._dl * G4ppx &
        * G5x + G5ppp * G5x + 2._dl * G4xx * G5x * H**2 - G5px * G5x * H**2 - 8._dl * G4x * G5xx * H**2 + 3._dl * &
        G5p * G5xx * H**2 + 2._dl * G4 * G5xxx * H**2))) - a**4 * dphi**3 * (2._dl * ddphi**2 * ((-2._dl) * G4 * &
        G4xxx + G4xx * G5p + 2._dl * G4x * (G4xx - G5px) + G4 * G5pxx - 2._dl * G5x**2 * H**2) + ddphi * dphi * &
        ((-(dH * G5x**2 * H)) + 2._dl * dphi * (4._dl * G4pxx * G4x - 4._dl * G4px * G4xx - 2._dl * G4pxx * G5p + &
        2._dl * G4xx * G5pp - 2._dl * G4x * G5ppx + G5p * G5ppx + 2._dl * G4px * G5px - G5pp * G5px + G4xx * G5x * &
        H**2 - 9._dl * G4x * G5xx * H**2 + 3._dl * G5p * G5xx * H**2 + 2._dl * G4 * G5xxx * H**2)) + dphi * (dddphi &
        * (4._dl * G4x * G4xx - 2._dl * G4xx * G5p - 2._dl * G4x * G5px + G5p * G5px + 2._dl * G5x**2 * H**2) + dphi &
        * ((-(dH**2 * G5x**2)) + dH * dphi * (2._dl * G4xx * G5x - G5px * G5x - 6._dl * G4x * G5xx + 3._dl * G5p * &
        G5xx) * H + H * (ddH * G5x**2 + dphi**2 * H * ((-4._dl) * G4xx**2 + 4._dl * G4x * G4xxx - 2._dl * G4xxx * &
        G5p + 8._dl * G4xx * G5px - 4._dl * G5px**2 - 6._dl * G4x * G5pxx + 3._dl * G5p * G5pxx - 4._dl * G4pxx * &
        G5x + 3._dl * G5ppx * G5x + 4._dl * G4px * G5xx - 2._dl * G5pp * G5xx + G5x * G5xx * H**2)))))) / (a**4 * &
        (2._dl * a**3 * G4 + a * dphi**2 * ((-2._dl) * G4x + G5p) - dphi**3 * G5x * H)**2)

    end subroutine horndeski_perturbeq_coefficients_sijdot

